//! Generate core's Unicode alphabetic, alphanumeric, numeric and case property intervals.
//! Run `cargo run -p flux-sourcegen --example unicode` with the selected
//! toolchain, or add `-- --check` to verify the committed tables.
use std::fmt::Write;

pub fn generate() -> String {
    let version = char::UNICODE_VERSION;
    let mut output = format!(
        "// Generated by crates/flux-sourcegen/examples/unicode.rs.\n// Unicode {}.{}.{}, from the selected Rust toolchain.\n\npub const UNICODE_VERSION: (u8, u8, u8) = ({}, {}, {});\n\n",
        version.0, version.1, version.2, version.0, version.1, version.2
    );
    // Keep case transitions out of the alphabetic/alphanumeric lookup table.
    for (table, case, function) in [
        ("PROPERTIES", false, "has_property"),
        ("CASE_PROPERTIES", true, "has_case_property"),
    ] {
        let mut intervals = Vec::new();
        let mut start = 0;
        let mut previous = 0;
        for code in 0..=0x110000 {
            let flags = char::from_u32(code).map_or(0, |c| {
                if case {
                    (u8::from(c.is_lowercase()) << 2) | (u8::from(c.is_uppercase()) << 3)
                } else {
                    u8::from(c.is_alphabetic()) | (u8::from(c.is_alphanumeric()) << 1) | (u8::from(c.is_numeric()) << 4)
                }
            });
            if flags != previous {
                if previous != 0 {
                    intervals.push((start, code - 1, previous));
                }
                start = code;
                previous = flags;
            }
        }
        writeln!(
            output,
            "const {table}: [(u32, u32, u8); {}] = [",
            intervals.len()
        )
        .unwrap();
        let first = intervals.first().unwrap().0;
        let last = intervals.last().unwrap().1;
        for (start, end, flags) in intervals {
            writeln!(output, "    (0x{start:x}, 0x{end:x}, {flags}),").unwrap();
        }
        output.push_str("];\n\n");
        output.push_str(
            r#"pub(crate) fn FUNCTION(c: char, mask: u8) -> bool {
    let code = c as u32;
    BOUNDS
    let mut low = 0;
    let mut high = TABLE.len();
    while low < high {
        let mid = low + (high - low) / 2;
        let (start, end, flags) = TABLE[mid];
        if code < start {
            high = mid;
        } else if code > end {
            low = mid + 1;
        } else {
            return flags & mask != 0;
        }
    }
    false
}
"#
            .replace("FUNCTION", function)
            .replace("TABLE", table)
            .replace(
                "BOUNDS",
                &format!("if code < {first} || code > {last} {{ return false; }}"),
            )
            .as_str(),
        );
        if !case {
            output.push('\n');
        }
    }
    output
}

fn main() {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../library/core/src/char_properties.rs");
    let output = generate();
    if std::env::args().any(|arg| arg == "--check") {
        assert_eq!(
            std::fs::read_to_string(&path).unwrap(),
            output,
            "regenerate Unicode tables with the selected toolchain"
        );
    } else {
        std::fs::write(path, output).unwrap();
    }
}
